    variant === "flat" ? leaves(entries) : entries,
    { x: 0, y: 0, width, height },
    0,
  );
  return result;
}
/** Compatibility layout helper: returns visible leaves, with original node/path metadata. */
export function computeTreeMapLayout(
  data: readonly TreeMapNode[],
  width: number,
  height: number,
): readonly LayoutRect[] {
  if (
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    width <= 0 ||
    height <= 0
  )
    return [];
  const model = buildTreeModel(data);
  if (model.error) return [];
  return layoutTree(model.roots, width, height, { maxDepth: 64 })
    .filter((tile) => !tile.expanded)
    .map((tile) => ({
      ...tile,
      node: tile.entry.node,
      depth: tile.entry.depth,
      colorIndex: tile.entry.colorIndex,
      path: tile.entry.path,
      percentage: tile.entry.percentage ?? 0,
    }));
}

import type { TreeMapNode } from "./layout";
export const DEFAULT_COLORS = [
  "#3b82f6",
  "#10b981",
  "#f59e0b",
  "#8b5cf6",
  "#06b6d4",
  "#ec4899",
] as const;
export interface TreeEntry {
  node: TreeMapNode;
  key: string;
  path: readonly string[];
  indexPath: readonly number[];
  value: number;
  depth: number;
  colorIndex: number;
  color: string;
  children: TreeEntry[];
  percentage: number | null;
  parentPercentage: number | null;
}
export function buildTreeModel(
  data: readonly TreeMapNode[],
  colors: readonly string[] = DEFAULT_COLORS,
) {
  let error: string | null = null;
  const entries: TreeEntry[] = [];
  const ancestry = new Set<TreeMapNode>();
  const palette = colors.length ? colors : DEFAULT_COLORS;
  if (palette.some((c) => typeof c !== "string" || !c.trim()))
    error = "colors must contain nonempty CSS colors.";
  function visit(
    node: TreeMapNode,
    indexPath: number[],
    path: string[],
    colorIndex: number,
    inherited: string,
  ): TreeEntry | null {
    const location = `Node ${indexPath.map((i) => i + 1).join(".")}`;
    if (!node || typeof node !== "object") {
      error ??= `${location}: provide a node object.`;
      return null;
    }
    if (ancestry.has(node)) {
      error ??= `${location}: a node cannot contain itself. Remove the hierarchy cycle.`;
      return null;
    }
    if (indexPath.length > 64) {
      error ??= `${location}: hierarchy exceeds 64 levels. Provide a shallower view.`;
      return null;
    }
    if (typeof node.name !== "string" || !node.name.trim())
      error ??= `${location}: provide a nonempty name.`;
    if (node.children !== undefined && !Array.isArray(node.children)) {
      error ??= `${location}: children must be an array.`;
      return null;
    }
    if (
      node.color !== undefined &&
      (typeof node.color !== "string" || !node.color.trim())
    )
      error ??= `${location}: color must be a nonempty CSS color.`;
    const color = node.color ?? inherited;
    const entry: TreeEntry = {
      node,
      key: indexPath.join("."),
      indexPath,
      path: [...path, node.name],
      depth: indexPath.length - 1,
      colorIndex,
      color,
      value: 0,
      children: [],
      percentage: null,
      parentPercentage: null,
    };
    entries.push(entry);
    ancestry.add(node);
    entry.children = (node.children ?? [])
      .map((child, index) =>
        visit(
          child,
          [...indexPath, index],
          entry.path as string[],
          colorIndex,
          color,
        ),
      )
      .filter((item): item is TreeEntry => item !== null);
    ancestry.delete(node);
    if (entry.children.length)
      entry.value = entry.children.reduce((sum, child) => sum + child.value, 0);
    else if (node.value === undefined && node.children?.length === 0)
      entry.value = 0;
    else if (
      typeof node.value !== "number" ||
      !Number.isFinite(node.value) ||
      node.value < 0
    )
      error ??= `${location} (${node.name}): value must be a finite nonnegative number. Supply the missing count or correct it.`;
    else entry.value = node.value;
    if (!Number.isFinite(entry.value))
      error ??= `${location}: total exceeds the numeric range. Rescale all values to a consistent unit.`;
    return entry;
  }
  const roots = data
    .map((node, i) => visit(node, [i], [], i, palette[i % palette.length]!))
    .filter((item): item is TreeEntry => item !== null);
  const total = roots.reduce((sum, node) => sum + node.value, 0);
  if (!Number.isFinite(total))
    error ??=
      "Hierarchy total exceeds the numeric range. Rescale all values to a consistent unit.";
  const byKey = new Map(entries.map((entry) => [entry.key, entry]));
  for (const entry of entries) {
    entry.percentage =
      total > 0 && Number.isFinite(total) ? (entry.value / total) * 100 : null;
    const parent =
      entry.indexPath.length > 1
        ? byKey.get(entry.indexPath.slice(0, -1).join("."))!.value
        : total;
    entry.parentPercentage =
      parent > 0 && Number.isFinite(parent)
        ? (entry.value / parent) * 100
        : null;
  }
  return { roots, entries, byKey, total, error };
}

"use client";
import { useState, type RefObject } from "react";
import { useIsomorphicLayoutEffect } from "@/lib/hooks";
/** Resolve CSS tokens and transparent paints against the actual chart surface. */
export function useTreeInk(
  root: RefObject<HTMLDivElement | null>,
  colors: readonly string[],
) {
  const [inks, setInks] = useState<Record<string, string>>({});
  useIsomorphicLayoutEffect(() => {
    const element = root.current;
    if (!element) return;
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = 1;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    if (!context) return;
    const ancestors: Element[] = [];
    for (let at: Element | null = element; at; at = at.parentElement)
      ancestors.unshift(at);
    const probe = document.createElement("span");
    probe.style.display = "none";
    element.appendChild(probe);
    const update = () => {
      const next: Record<string, string> = {};
      for (const color of colors) {
        context.clearRect(0, 0, 1, 1);
        context.fillStyle = "white";
        context.fillRect(0, 0, 1, 1);
        for (const ancestor of ancestors) {
          context.fillStyle = getComputedStyle(ancestor).backgroundColor;
          context.fillRect(0, 0, 1, 1);
        }
        probe.style.color = "var(--muted)";
        context.fillStyle = getComputedStyle(probe).color;
        context.fillRect(0, 0, 1, 1);
        probe.style.color = "";
        probe.style.color = color;
        context.fillStyle = getComputedStyle(probe).color;
        context.fillRect(0, 0, 1, 1);
        const pixel = context.getImageData(0, 0, 1, 1).data;
        const channel = (v: number) => {
          const c = v / 255;
          return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
        };
        const luminance =
          0.2126 * channel(pixel[0]!) +
          0.7152 * channel(pixel[1]!) +
          0.0722 * channel(pixel[2]!);
        next[color] =
          (luminance + 0.05) / 0.05 >= 1.05 / (luminance + 0.05)
            ? "#000000"
            : "#ffffff";
      }
      setInks((old) =>
        colors.every((color) => old[color] === next[color]) ? old : next,
      );
    };
    update();
    const observer = new MutationObserver(update);
    ancestors.forEach((ancestor) =>
      observer.observe(ancestor, {
        attributes: true,
        attributeFilter: ["class", "style"],
      }),
    );
    const media = window.matchMedia("(prefers-color-scheme: dark)");
    media.addEventListener("change", update);
    const transition = (event: TransitionEvent) => {
      if (
        event.propertyName === "background-color" &&
        ancestors.includes(event.target as Element)
      )
        update();
    };
    document.documentElement.addEventListener("transitionend", transition);
    return () => {
      observer.disconnect();
      media.removeEventListener("change", update);
      document.documentElement.removeEventListener("transitionend", transition);
      probe.remove();
    };
  }, [root, colors]);
  return inks;
}
